import{_ as t,o,c as r,a3 as a}from"./chunks/framework.Ki30n65y.js";const i="/depgate/screenshots/policies.png",s="/depgate/screenshots/policy-view.png",u=JSON.parse('{"title":"Policies overview","description":"","frontmatter":{},"headers":[],"relativePath":"admin/policies.md","filePath":"admin/policies.md"}'),n={name:"admin/policies.md"};function l(d,e,c,p,h,g){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="policies-overview" tabindex="-1">Policies overview <a class="header-anchor" href="#policies-overview" aria-label="Permalink to &quot;Policies overview&quot;">​</a></h1><p>Policies are the rules that decide which package versions your organization may use. This page explains how policies work. To create one step by step, see <a href="./create-policy">Create a policy</a>; for every rule and its options, see <a href="./policy-rules">Policy rules</a>.</p><p><img src="'+i+'" alt="The Policies page"></p><h2 id="anatomy-of-a-policy" tabindex="-1">Anatomy of a policy <a class="header-anchor" href="#anatomy-of-a-policy" aria-label="Permalink to &quot;Anatomy of a policy&quot;">​</a></h2><p>Each policy has:</p><table tabindex="0"><thead><tr><th>Part</th><th>Description</th></tr></thead><tbody><tr><td><strong>Name and description</strong></td><td>What the policy is for, in your own words. The name is shown in block messages and the Decision Ledger.</td></tr><tr><td><strong>Rule</strong></td><td>Exactly one rule: Packages, Release type, Release age, Vulnerability, License, Namespace protection or Project health.</td></tr><tr><td><strong>Action</strong></td><td><strong>Block</strong> or <strong>Allow</strong>. Allow is available only for the Packages rule.</td></tr><tr><td><strong>Enforcement</strong></td><td>For Block policies: <strong>Enforce</strong> (block matching versions) or <strong>Monitor only</strong> (record what would be blocked).</td></tr><tr><td><strong>Priority</strong></td><td>A number. Lower numbers are evaluated first.</td></tr><tr><td><strong>Ecosystem</strong></td><td>One ecosystem, or All.</td></tr><tr><td><strong>Applies to</strong></td><td>All repositories, or only selected ones.</td></tr><tr><td><strong>Enabled</strong></td><td>A disabled policy is kept but not evaluated.</td></tr></tbody></table><p>A version gets the policy&#39;s action when it is in the policy&#39;s ecosystem and repositories, and matches the rule.</p><h2 id="starter-policies" tabindex="-1">Starter policies <a class="header-anchor" href="#starter-policies" aria-label="Permalink to &quot;Starter policies&quot;">​</a></h2><p>A new installation comes with eight policies, so the gateway protects something from its first day. Four enforce and four monitor; edit, disable or delete them as you like, and nothing recreates them.</p><table tabindex="0"><thead><tr><th>Policy</th><th>Rule</th><th>Mode</th></tr></thead><tbody><tr><td>Quarantine new releases</td><td>Versions published less than 72 hours ago</td><td>Enforce</td></tr><tr><td>Critical vulnerabilities</td><td>A known vulnerability scored CVSS 9.0 or higher</td><td>Enforce</td></tr><tr><td>No pre-release versions</td><td>Alpha, beta, release candidate, dev and snapshot versions</td><td>Enforce</td></tr><tr><td>Go pseudo-versions</td><td>Go modules pulled at an untagged commit</td><td>Enforce</td></tr><tr><td>Likely exploited vulnerabilities</td><td>EPSS exploit probability of 50% or higher; vulnerabilities without a score are ignored</td><td>Monitor</td></tr><tr><td>Strong copyleft licenses</td><td>GPL, AGPL, SSPL and EUPL in every form</td><td>Monitor</td></tr><tr><td>Unmaintained packages</td><td>Latest release more than two years old</td><td>Monitor</td></tr><tr><td>Low project health</td><td>OpenSSF Scorecard below 3 of 10; projects without a score are not matched</td><td>Monitor</td></tr></tbody></table><p>The monitor policies record what they would have blocked without blocking anything. Review the report under <strong>Monitoring</strong> and switch a policy to enforce when the report is acceptable. Malicious packages need no policy: the built-in feed blocks them always. Add an <a href="/depgate/admin/namespace-protection">internal namespace</a> policy for your own package scopes; it needs your names, so it cannot be shipped.</p><h2 id="one-rule-per-policy" tabindex="-1">One rule per policy <a class="header-anchor" href="#one-rule-per-policy" aria-label="Permalink to &quot;One rule per policy&quot;">​</a></h2><p>Each policy does exactly one thing, so its effect is easy to read and its block messages are precise. To block for several reasons, create several policies: for example one for critical vulnerabilities and one for banned licenses.</p><table tabindex="0"><thead><tr><th>Rule</th><th>Blocks</th></tr></thead><tbody><tr><td><strong>Packages</strong></td><td>Named packages, optionally only some versions. Can also <strong>Allow</strong>.</td></tr><tr><td><strong>Release type</strong></td><td>Pre-release, development, snapshot or Go pseudo-versions.</td></tr><tr><td><strong>Release age</strong></td><td>Versions that are too new, or packages that are no longer maintained.</td></tr><tr><td><strong>Vulnerability</strong></td><td>Listed CVEs, or vulnerabilities above a CVSS score and/or an EPSS exploit likelihood.</td></tr><tr><td><strong>License</strong></td><td>Licenses outside your approved list, or on your banned list.</td></tr><tr><td><strong>Namespace protection</strong></td><td>Your internal package names when they come from anywhere but your internal registries.</td></tr><tr><td><strong>Project health</strong></td><td>Packages whose source repository scores low on the OpenSSF Scorecard.</td></tr></tbody></table><h2 id="evaluation-order" tabindex="-1">Evaluation order <a class="header-anchor" href="#evaluation-order" aria-label="Permalink to &quot;Evaluation order&quot;">​</a></h2><p>For each version, DepGate first applies namespace protection, exceptions and the malware list (see <a href="/depgate/guide/how-it-works#the-order-of-checks">the order of checks</a>). It then evaluates the enabled policies that apply to the request in <strong>priority order, lowest number first</strong>. The <strong>first policy that matches decides</strong>, and later policies are not evaluated.</p><p>This makes priority meaningful when you combine Allow and Block:</p><table tabindex="0"><thead><tr><th>Priority</th><th>Policy</th><th>Effect</th></tr></thead><tbody><tr><td>5</td><td>Allow <code>@acme/*</code> (Packages)</td><td>Your own packages are always allowed.</td></tr><tr><td>10</td><td>Block CVSS 9.0 or higher (Vulnerability)</td><td>Applies to every other package.</td></tr><tr><td>20</td><td>Block banned licenses (License)</td><td>Applies to packages that passed the policies above.</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Allow skips everything below it</p><p>An Allow policy lets matching versions through without evaluating any lower-priority policy, including vulnerability checks. Use Allow only for packages you trust, and give it a narrow package list.</p></div><h3 id="reorder-policies" tabindex="-1">Reorder policies <a class="header-anchor" href="#reorder-policies" aria-label="Permalink to &quot;Reorder policies&quot;">​</a></h3><p>The Policies page lists policies in evaluation order. Change the order by dragging a row by its handle, or with the up and down arrows. Changes save immediately.</p><h2 id="enforce-or-monitor" tabindex="-1">Enforce or monitor <a class="header-anchor" href="#enforce-or-monitor" aria-label="Permalink to &quot;Enforce or monitor&quot;">​</a></h2><p>A Block policy is either:</p><ul><li><strong>Enforce</strong>: matching versions are blocked.</li><li><strong>Monitor only (log, don&#39;t block)</strong>: nothing is blocked. Each download the policy would have blocked is recorded on the <strong>Monitoring</strong> page.</li></ul><p>Monitor broad rules first (vulnerability, license, release age, release type, project health), review what they would break, approve the packages that must keep working, then enforce. See <a href="./monitoring">Monitor before enforcing</a>.</p><h2 id="limit-a-policy-to-some-repositories" tabindex="-1">Limit a policy to some repositories <a class="header-anchor" href="#limit-a-policy-to-some-repositories" aria-label="Permalink to &quot;Limit a policy to some repositories&quot;">​</a></h2><p>By default a policy applies to <strong>All repositories</strong> of its ecosystem, including ones added later. Choose <strong>Selected repositories</strong> to limit it:</p><ul><li>A policy on a <strong>remote</strong> repository applies to every package that remote serves, whichever URL the client used (the remote&#39;s own URL, <code>all</code>, or a virtual repository that contains it).</li><li>A policy on a <strong>virtual</strong> repository applies to everything downloaded through that URL.</li></ul><p>For a request through <code>/npm/all/</code>, DepGate applies the policies for all repositories, the policies on <code>all</code>&#39;s URL, and the policies on the remote that actually served the package.</p><p><code>all</code> itself cannot be selected: a policy on a remote already covers that remote&#39;s packages through <code>all</code>. Use the <strong>Repository</strong> filter on the Policies page to list the policies that apply to one repository.</p><p>If you delete the last repository a policy is limited to, DepGate disables the policy rather than widening it to every repository.</p><h2 id="approved-packages" tabindex="-1">Approved packages <a class="header-anchor" href="#approved-packages" aria-label="Permalink to &quot;Approved packages&quot;">​</a></h2><p>A Block policy can have <strong>approved packages</strong>: exceptions that stop only this policy from matching, usually created from the Monitoring page. They are listed in the policy view and form, with <strong>Revoke</strong>. Every other policy still applies to them. See <a href="./exceptions#policy-scoped-approvals">Exceptions and waivers</a>.</p><h2 id="view-a-policy" tabindex="-1">View a policy <a class="header-anchor" href="#view-a-policy" aria-label="Permalink to &quot;View a policy&quot;">​</a></h2><p>Choose the eye icon on a row to open the policy view. It shows the action, scope, rule settings, priority, status and approved packages.</p><p><img src="'+s+'" alt="Viewing a policy"></p><h2 id="disable-or-delete" tabindex="-1">Disable or delete <a class="header-anchor" href="#disable-or-delete" aria-label="Permalink to &quot;Disable or delete&quot;">​</a></h2><ul><li>Turn off the <strong>Status</strong> switch on the Policies page (or <strong>Enabled</strong> in the form) to stop evaluating a policy without losing it.</li><li>Delete a policy with the trash icon on its row. Deleting also removes its monitoring data and its approved packages.</li></ul><p>Every change to a policy is recorded in the <a href="./audit-log">Audit Log</a>.</p>',39)])])}const m=t(n,[["render",l]]);export{u as __pageData,m as default};
